function buildAction07PromptJa(context: Action07PromptContext): string {
  const {
    analysisStartDate,
    analysisEndDate,
    aggregatedReportData,
    productivityMetrics,
    prioritizedIssues,
    recurrencePatterns,
    proposedImprovements,
    managerName,
  } = context;

  const issuesSummary = prioritizedIssues
    .slice(0, 5)
    .map(
      (issue, idx) =>
        `${idx + 1}. ${issue.title} (優先度: ${issue.priority}, 発生回数: ${issue.occurrenceCount})`
    )
    .join("\n");

  const improvementsSummary = proposedImprovements
    .slice(0, 3)
    .map(
      (imp, idx) =>
        `${idx + 1}. ${imp.title} (実装難易度: ${imp.implementationDifficulty}, 予想期間: ${imp.estimatedImplementationDays}日)`
    )
    .join("\n");

  const recurrenceSummary = recurrencePatterns
    .slice(0, 3)
    .map(
      (pattern, idx) =>
        `${idx + 1}. ${pattern.issueCategory} (再発回数: ${pattern.recurrenceCount}, 根本原因仮説: ${pattern.rootCauseHypothesis})`
    )
    .join("\n");

  return `あなたは朝会報告管理システムの分析エージェントです。
以下の分析結果をもとに、${managerName}部長向けの包括的な報告書を作成してください。

【分析対象期間】
開始日: ${analysisStartDate}
終了日: ${analysisEndDate}

【報告データ集約結果】
- 総報告件数: ${aggregatedReportData.totalReports}
- 提出済み: ${aggregatedReportData.submittedReports}
- 未提出メンバー数: ${aggregatedReportData.nonSubmittedMembers.length}

【生産性指標】
- 総課題件数: ${productivityMetrics.totalIssueCount}
- 平均解決日数: ${productivityMetrics.averageResolutionDays}日
- 対応速度スコア: ${productivityMetrics.responseSpeedScore}/100
- 課題解決率: ${productivityMetrics.issueResolutionRate}%

【優先度別課題（上位5件）】
${issuesSummary}

【検出された再発パターン（上位3件）】
${recurrenceSummary}

【提案される改善施策（上位3件）】
${improvementsSummary}

【報告書作成要件】
1. エグゼクティブサマリー（3-5行）を作成してください
2. 主要な発見事項を5-7項目列挙してください
3. 推奨アクションを優先度順に整理してください（最大10項目）
4. 各推奨アクションには実行責任者と目標完了日を含めてください
5. マークダウン形式で構造化してください
6. 部長が朝会で即座に活用できる実行可能な内容にしてください

【出力形式】
以下のJSON形式で出力してください：
{
  "reportTitle": "報告書のタイトル",
  "reportContent": "マークダウン形式の報告書本文",
  "executiveSummary": "エグゼクティブサマリー",
  "keyFindings": ["発見事項1", "発見事項2", ...],
  "recommendedActions": [
    {
      "actionId": "ACT001",
      "action": "推奨アクション",
      "priority": "immediate|high|medium|low",
      "owner": "実行責任者",
      "targetCompletionDate": "YYYY-MM-DD"
    },
    ...
  ],
  "generatedAt": "ISO 8601形式のタイムスタンプ",
  "distributionTargets": ["${managerName}", "経営層", "関連部門"]
}`;
}

